const execution = $json.execution ?? {};
const workflow = $json.workflow ?? {};
const error_message = execution.error?.message ?? $json.trigger?.error?.message ?? 'unknown error';
const event = {
  event_type: 'workflow_failed',
  workflow_name: workflow.name ?? 'unknown',
  execution_id: execution.id ?? null,
  last_node: execution.lastNodeExecuted ?? null,
  error_message,
  occurred_at: new Date().toISOString()
};
const quote = (value) => `'${String(value ?? '').replaceAll("'", "''")}'`;
return [{ json: {
  ...event,
  audit_sql: `INSERT INTO audit_events(entity_type, entity_id, event_type, actor_type, actor_id, payload_json) VALUES ('workflow', 0, 'workflow_failed', 'system', 'n8n', ${quote(JSON.stringify(event))}::jsonb);`
} }];

